INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('1001d933-c25e-5f2c-bded-da7331b0bb45', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 9, 9, 'A star of luminosity 3.0 × 10²⁷ W is 2.0 × 10¹⁷ m from the Earth. Calculate the radiant flux intensity at the Earth, in units of 10⁻⁹ W m⁻².', NULL, 1, 'numeric'::answer_type, '5.968', '10⁻⁹ W m⁻²', false, NULL, false, NULL, 'F = L/4πd² = 3.0 × 10²⁷ ÷ (4π × (2.0 × 10¹⁷)²) = 5.97 × 10⁻⁹ W m⁻². Mark scheme (2 marks). C1: F = L/4πd². A1: F = 5.97 × 10⁻⁹ W m⁻².', 2, NULL, NULL),
('9e4c4dc4-9ce3-571a-a991-b8fc4f3282c6', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 10, 10, 'What is the luminosity of a star?', NULL, 1, 'multiple_choice'::answer_type, 'The total power it radiates as electromagnetic radiation', NULL, false, NULL, false, NULL, 'Luminosity is measured in watts. Mark scheme (1 mark). B1: C (The total power it radiates as electromagnetic radiation).', 1, NULL, NULL),
('0d88646b-6480-5adb-911d-4965d69ac017', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 11, 11, 'The flux intensity from a lamp is 12 W m⁻² at a certain distance. Calculate the flux intensity at half that distance.', NULL, 1, 'numeric'::answer_type, '48', 'W m⁻²', false, NULL, false, NULL, 'F ∝ 1/d²: halving d multiplies F by 4: F = 12 × 4 = 48 W m⁻². Mark scheme (2 marks). C1: inverse square. A1: F = 48 W m⁻².', 2, NULL, NULL),
('8c8a1594-621e-5276-a28c-e0a921bb007d', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 12, 12, 'What is meant by a standard candle in astronomy?', NULL, 1, 'multiple_choice'::answer_type, 'An object of known luminosity, whose distance can be found from the flux received', NULL, false, NULL, false, NULL, 'Measuring F and knowing L gives d. Mark scheme (1 mark). B1: A (An object of known luminosity, whose distance can be found from the flux received).', 1, NULL, NULL),
('5369cdfb-123b-506c-ada0-3bf8ef81712a', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 13, 13, 'A star''s luminosity is 2.0 × 10³⁰ W. Calculate the total power passing through a sphere of radius 1.0 × 10¹⁸ m centred on the star.', NULL, 1, 'numeric'::answer_type, '2e30', 'W', false, NULL, false, NULL, 'All the power crosses any sphere around the star: P = 2.0 × 10³⁰ × 1 = 2.0 × 10³⁰ W. Mark scheme (2 marks). C1: energy conservation. A1: P = 2.0 × 10³⁰ W.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 240" role="img" aria-labelledby="fga3b613d8-t fga3b613d8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga3b613d8-t">Sphere around a star</title><desc id="fga3b613d8-d">A star of luminosity 2.0 × 10³⁰ W radiating equally in all directions, with part of a sphere of radius 1.0 × 10¹⁸ m centred on it.</desc><path d="M269.2,235 A230,230 0 0,0 269.2,5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="82.8" y1="125.7" x2="121" y2="142.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,144.4 118.8,144.5 120.9,139.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="122.9" x2="124.6" y2="131.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,132.5 122.8,133.8 123.9,128.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="84" y1="120" x2="125.8" y2="120" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,120 124.6,122.5 124.6,117.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="117.1" x2="124.6" y2="108.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,107.5 123.9,111.1 122.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="82.8" y1="114.3" x2="121" y2="97.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,95.6 120.9,100.1 118.8,95.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><circle cx="70" cy="120" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="146" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 × 10³⁰ W</text><rect x="296" y="110" width="10" height="20" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polygon points="70,166 76.3,163 76.3,169" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="166" x2="295.1" y2="166" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,166 293.7,169 293.7,163" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185" y="178" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 × 10¹⁸ m</text></svg>', 'A star of luminosity 2.0 × 10³⁰ W radiating equally in all directions, with part of a sphere of radius 1.0 × 10¹⁸ m centred on it.'),
('5577cb2b-3627-5def-81af-d69aad7e5c8b', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 14, 14, 'Which type of object is used as a standard candle for measuring very large distances?', NULL, 1, 'multiple_choice'::answer_type, 'Type 1a supernovae', NULL, false, NULL, false, NULL, 'Type 1a supernovae reach almost the same peak luminosity. Mark scheme (1 mark). B1: D (Type 1a supernovae).', 1, NULL, NULL),
('045890aa-eddf-5bdd-ac27-3b6bc2afcf1d', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 15, 15, 'Express a distance of 4.2 light-years in metres, in units of 10¹⁶ m (1 light-year = 9.46 × 10¹⁵ m).', NULL, 1, 'numeric'::answer_type, '3.973', '10¹⁶ m', false, NULL, false, NULL, 'd = 4.2 × 9.46 × 10¹⁵ = 3.97 × 10¹⁶ m. Mark scheme (2 marks). C1: × 9.46 × 10¹⁵. A1: d = 3.97 × 10¹⁶ m.', 2, NULL, NULL),
('eef7bb4e-b78d-58a3-a85a-e8e5bdc0a69b', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 16, 16, 'Which variable stars act as standard candles because their luminosity is linked to their period?', NULL, 1, 'multiple_choice'::answer_type, 'Cepheid variables', NULL, false, NULL, false, NULL, 'Their period–luminosity relationship gives L. Mark scheme (1 mark). B1: B (Cepheid variables).', 1, NULL, NULL),
('41b89375-70e7-541c-b316-daf3343bf748', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 17, 17, 'A standard candle of luminosity 5.0 × 10²⁸ W gives a flux intensity of 1.0 × 10⁻⁸ W m⁻². Calculate its distance in units of 10¹⁸ m.', NULL, 1, 'numeric'::answer_type, '0.6308', '10¹⁸ m', false, NULL, false, NULL, 'd = √(L/4πF) = √(5.0 × 10²⁸ ÷ (4π × 1.0 × 10⁻⁸)) = 6.31 × 10¹⁷ m. Mark scheme (2 marks). C1: rearranged formula. A1: d = 0.631 × 10¹⁸ m.', 2, NULL, NULL),
('c4b4e2f6-981a-57a5-afe9-1da53b231832', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 18, 18, 'In which unit is radiant flux intensity measured?', NULL, 1, 'multiple_choice'::answer_type, 'W m⁻²', NULL, false, NULL, false, NULL, 'It is power per unit area. Mark scheme (1 mark). B1: C (W m⁻²).', 1, NULL, NULL),
('7457ab31-cca7-5e90-84b4-3f2539ba1514', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 19, 19, 'The distance to a star is tripled. By what factor does the flux intensity received fall?', NULL, 1, 'numeric'::answer_type, '9', NULL, false, NULL, false, NULL, 'F ∝ 1/d²: factor = 3² = 9. Mark scheme (2 marks). C1: inverse square. A1: factor = 9.', 2, NULL, NULL),
('09dda145-e406-5f0d-99f8-9ec1055bf5da', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 20, 20, 'Why does the flux intensity from a star fall with distance?', NULL, 1, 'multiple_choice'::answer_type, 'The same power spreads over a larger spherical area', NULL, false, NULL, false, NULL, 'Area of a sphere = 4πd². Mark scheme (1 mark). B1: A (The same power spreads over a larger spherical area).', 1, NULL, NULL),
('b6a08107-d273-5749-bb76-9a5eea18d2ce', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 21, 21, 'Calculate the area of a sphere of radius 1.5 × 10¹¹ m, in units of 10²³ m².', NULL, 1, 'numeric'::answer_type, '2.827', '10²³ m²', false, NULL, false, NULL, 'A = 4πr² = 4π × (1.5 × 10¹¹)² = 2.83 × 10²³ m². Mark scheme (2 marks). C1: A = 4πr². A1: A = 2.83 × 10²³ m².', 2, NULL, NULL),
('21d21284-ada7-5f20-8cd3-3ee697ff95e1', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 22, 22, 'Two identical stars are at distances d and 2d from the Earth. How does the flux from the nearer star compare?', NULL, 1, 'multiple_choice'::answer_type, 'It is four times larger', NULL, false, NULL, false, NULL, 'F ∝ 1/d², so the star at half the distance gives 2² = 4 times the flux. Mark scheme (1 mark). B1: D (It is four times larger).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg558110da-t fg558110da-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg558110da-t">Two identical stars</title><desc id="fg558110da-d">Two identical stars on the same line of sight from the Earth, at distances d and 2d.</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><circle cx="46" cy="62" r="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><line x1="241" y1="62" x2="246" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="237.8" y1="69.8" x2="241.3" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="73" x2="230" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="222.2" y1="69.8" x2="218.7" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="219" y1="62" x2="214" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="222.2" y1="54.2" x2="218.7" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="51" x2="230" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="237.8" y1="54.2" x2="241.3" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="230" cy="62" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="230" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><line x1="425" y1="62" x2="430" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="421.8" y1="69.8" x2="425.3" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="414" y1="73" x2="414" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="406.2" y1="69.8" x2="402.7" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="403" y1="62" x2="398" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="406.2" y1="54.2" x2="402.7" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="414" y1="51" x2="414" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="421.8" y1="54.2" x2="425.3" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="414" cy="62" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="414" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="225.1" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,116 223.7,119 223.7,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="138" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">d</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="230" y1="74" x2="230" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><polygon points="46,146 52.3,143 52.3,149" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="146" x2="409.1" y2="146" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="414,146 407.7,149 407.7,143" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="230" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2d</text><line x1="46" y1="74" x2="46" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="414" y1="74" x2="414" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'Two identical stars on the same line of sight from the Earth, at distances d and 2d.'),
('6e64bc0c-8e2f-5f36-8ea1-81163311cb22', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 23, 23, 'A star 8.0 × 10¹⁶ m away gives a flux intensity of 2.0 × 10⁻⁹ W m⁻². Calculate its luminosity, in units of 10²⁶ W.', NULL, 1, 'numeric'::answer_type, '1.608', '10²⁶ W', false, NULL, false, NULL, 'L = 4πd²F = 4π × (8.0 × 10¹⁶)² × 2.0 × 10⁻⁹ = 1.61 × 10²⁶ W. Mark scheme (2 marks). C1: L = 4πd²F. A1: L = 1.61 × 10²⁶ W.', 2, NULL, NULL),
('9e4d11c7-359d-55d6-9979-8a970998b749', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 24, 24, 'What must be known about a standard candle to find its distance?', NULL, 1, 'multiple_choice'::answer_type, 'Its luminosity', NULL, false, NULL, false, NULL, 'With L known and F measured, d = √(L/4πF). Mark scheme (1 mark). B1: B (Its luminosity).', 1, NULL, NULL),
('f966fd2b-4c67-5ce9-b119-4d5177f957e1', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 25, 25, 'Express 1.0 parsec (3.09 × 10¹⁶ m) in light-years (1 ly = 9.46 × 10¹⁵ m).', NULL, 1, 'numeric'::answer_type, '3.266', 'ly', false, NULL, false, NULL, '1 pc = 3.09 × 10¹⁶ ÷ 9.46 × 10¹⁵ = 3.27 ly. Mark scheme (1 mark). A1: d = 3.27 ly.', 1, NULL, NULL),
('4fb48504-ba1f-53e8-9fe3-0f3347520932', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 26, 26, 'A lighthouse lamp radiates 2.0 kW equally in all directions. Calculate the intensity 500 m away, in units of 10⁻⁴ W m⁻².', NULL, 1, 'numeric'::answer_type, '6.366', '10⁻⁴ W m⁻²', false, NULL, false, NULL, 'I = 2.0 × 10³ ÷ (4π × 500²) = 6.37 × 10⁻⁴ W m⁻². Mark scheme (2 marks). C1: I = P/4πd². A1: I = 6.37 × 10⁻⁴ W m⁻².', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 240" role="img" aria-labelledby="fgcc03f533-t fgcc03f533-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgcc03f533-t">Lighthouse lamp</title><desc id="fgcc03f533-d">A lamp of power 2.0 kW radiating equally in all directions, with a detector 500 m away on a sphere centred on the lamp.</desc><path d="M269.2,235 A230,230 0 0,0 269.2,5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="82.8" y1="125.7" x2="121" y2="142.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,144.4 118.8,144.5 120.9,139.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="122.9" x2="124.6" y2="131.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,132.5 122.8,133.8 123.9,128.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="84" y1="120" x2="125.8" y2="120" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,120 124.6,122.5 124.6,117.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="117.1" x2="124.6" y2="108.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,107.5 123.9,111.1 122.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="82.8" y1="114.3" x2="121" y2="97.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,95.6 120.9,100.1 118.8,95.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><circle cx="70" cy="120" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="146" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 kW</text><rect x="296" y="110" width="10" height="20" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polygon points="70,166 76.3,163 76.3,169" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="166" x2="295.1" y2="166" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,166 293.7,169 293.7,163" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185" y="178" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">500 m</text></svg>', 'A lamp of power 2.0 kW radiating equally in all directions, with a detector 500 m away on a sphere centred on the lamp.'),
('34176831-164f-5043-9f8a-8591825965b9', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 27, 27, 'A Cepheid variable has a luminosity of 4.0 × 10²⁹ W and gives a flux intensity of 3.2 × 10⁻¹¹ W m⁻² at the Earth. Calculate its distance in light-years (1 ly = 9.46 × 10¹⁵ m).', NULL, 2, 'numeric'::answer_type, '3334', 'ly', false, NULL, false, NULL, 'd = √(4.0 × 10²⁹ ÷ (4π × 3.2 × 10⁻¹¹)) = 3.154 × 10¹⁹ m. In ly: 3.154 × 10¹⁹ ÷ 9.46 × 10¹⁵ = 3330. Mark scheme (3 marks). C1: d = √(L/4πF). C1: m to ly. A1: d = 3330 ly.', 3, NULL, NULL),
('446add85-8de9-501a-a9ed-0f31e9fcddc3', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 28, 28, 'Two stars appear equally bright. Star X is 3.0 times further away than star Y. Calculate (luminosity of X) ÷ (luminosity of Y).', NULL, 2, 'numeric'::answer_type, '9', NULL, false, NULL, false, NULL, 'Equal F means L ∝ d²: ratio = 3.0² = 9.0. Mark scheme (3 marks). C1: L = 4πd²F. C1: ratio. A1: ratio = 9.0.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg4f7d072b-t fg4f7d072b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4f7d072b-t">Two equally bright stars</title><desc id="fg4f7d072b-d">Stars Y and X give the same flux at the Earth; Y is at distance d and X at 3.0d.</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><circle cx="46" cy="62" r="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><line x1="179.7" y1="62" x2="184.7" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="176.4" y1="69.8" x2="180" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="168.7" y1="73" x2="168.7" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160.9" y1="69.8" x2="157.4" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157.7" y1="62" x2="152.7" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160.9" y1="54.2" x2="157.4" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="168.7" y1="51" x2="168.7" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="176.4" y1="54.2" x2="180" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="168.7" cy="62" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="168.7" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Y</text><line x1="425" y1="62" x2="430" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="421.8" y1="69.8" x2="425.3" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="414" y1="73" x2="414" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="406.2" y1="69.8" x2="402.7" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="403" y1="62" x2="398" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="406.2" y1="54.2" x2="402.7" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="414" y1="51" x2="414" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="421.8" y1="54.2" x2="425.3" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="414" cy="62" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="414" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">X</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="163.8" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="168.7,116 162.3,119 162.3,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="107.3" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">d</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="168.7" y1="74" x2="168.7" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><polygon points="46,146 52.3,143 52.3,149" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="146" x2="409.1" y2="146" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="414,146 407.7,149 407.7,143" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="230" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0d</text><line x1="46" y1="74" x2="46" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="414" y1="74" x2="414" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'Stars Y and X give the same flux at the Earth; Y is at distance d and X at 3.0d.'),
('6b83e670-b5e3-5eff-8ea8-0ae2219e031f', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 29, 29, 'Why are Cepheid variables useful for measuring distances?', NULL, 2, 'multiple_choice'::answer_type, 'Their period of variation depends on their luminosity, so measuring the period gives L', NULL, false, NULL, false, NULL, 'Then d follows from L and the measured flux. Mark scheme (3 marks). C1: period–luminosity relation. C1: L then d. A1: C (Their period of variation depends on their luminosity, so measuring the period gives L).', 3, NULL, NULL),
('03d58921-a72c-5ade-89a6-635ced1cc767', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 30, 30, 'A type 1a supernova has a peak luminosity of 1.0 × 10³⁶ W and a peak flux intensity at the Earth of 2.0 × 10⁻¹⁵ W m⁻². Calculate its distance in Mpc (1 Mpc = 3.09 × 10²² m).', NULL, 2, 'numeric'::answer_type, '204.1', 'Mpc', false, NULL, false, NULL, 'd = √(1.0 × 10³⁶ ÷ (4π × 2.0 × 10⁻¹⁵)) = 6.308 × 10²⁴ m. In Mpc: 6.308 × 10²⁴ ÷ 3.09 × 10²² = 204. Mark scheme (4 marks). C1: rearranged. C1: value in m. C1: m to Mpc. A1: d = 204 Mpc.', 4, NULL, NULL),
('99d99f08-34e9-50dc-a9f1-1a9f53b122b0', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 31, 31, 'The Sun''s luminosity is 3.8 × 10²⁶ W. Calculate the flux intensity at Mars, 2.3 × 10¹¹ m from the Sun.', NULL, 2, 'numeric'::answer_type, '571.6', 'W m⁻²', false, NULL, false, NULL, 'F = 3.8 × 10²⁶ ÷ (4π × (2.3 × 10¹¹)²) = 572 W m⁻². Mark scheme (3 marks). C1: formula. C1: substitution. A1: F = 572 W m⁻².', 3, NULL, NULL),
('cd3efab9-18b4-5e46-be70-7a0006700325', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 32, 32, 'A standard candle is partly hidden by dust, which absorbs some of its light. How does this affect the distance calculated from it?', NULL, 2, 'multiple_choice'::answer_type, 'The distance is overestimated', NULL, false, NULL, false, NULL, 'Less flux suggests a larger d. Mark scheme (3 marks). C1: F reduced. C1: d = √(L/4πF) larger. A1: A (The distance is overestimated).', 3, NULL, NULL),
('fabc4807-6674-59e3-8f3b-40a6f8dd3e96', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 33, 33, 'The flux intensity from a star falls from 6.4 × 10⁻⁹ W m⁻² to 1.6 × 10⁻⁹ W m⁻² when measured from a point further away along the same line. Calculate (new distance) ÷ (old distance).', NULL, 2, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'd ∝ 1/√F: ratio = √(6.4 ÷ 1.6) = 2.0. Mark scheme (3 marks). C1: F ∝ 1/d². C1: square root. A1: ratio = 2.0.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 214" role="img" aria-labelledby="fge48a2cb9-t fge48a2cb9-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge48a2cb9-t">Flux at two points</title><desc id="fge48a2cb9-d">A star and two points on the same line away from it: the flux is 6.4 × 10⁻⁹ W m⁻² at the nearer point and 1.6 × 10⁻⁹ W m⁻² at the further one. Not to scale.</desc><line x1="46" y1="62" x2="404.7" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="57" y1="62" x2="62" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="53.8" y1="69.8" x2="57.3" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="73" x2="46" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="38.2" y1="69.8" x2="34.7" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="35" y1="62" x2="30" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="38.2" y1="54.2" x2="34.7" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="51" x2="46" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="53.8" y1="54.2" x2="57.3" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46" cy="62" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">star</text><circle cx="209" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="209" y="90" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.4 × 10⁻⁹ W m⁻²</text><circle cx="404.7" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="404.7" y="90" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.6 × 10⁻⁹ W m⁻²</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="204.1" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="209,116 202.7,119 202.7,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="127.5" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">old distance</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="209" y1="74" x2="209" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><polygon points="46,146 52.3,143 52.3,149" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="146" x2="399.8" y2="146" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="404.7,146 398.3,149 398.3,143" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="225.3" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">new distance</text><line x1="46" y1="74" x2="46" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="404.7" y1="74" x2="404.7" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><text x="452" y="206" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">not to scale</text></svg>', 'A star and two points on the same line away from it: the flux is 6.4 × 10⁻⁹ W m⁻² at the nearer point and 1.6 × 10⁻⁹ W m⁻² at the further one. Not to scale.'),
('ba043b29-1f17-5990-86c5-451ebc47c9bb', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 34, 34, 'A star 50 light-years away (1 ly = 9.46 × 10¹⁵ m) gives a flux intensity of 4.0 × 10⁻⁹ W m⁻². Calculate its luminosity in units of 10²⁷ W.', NULL, 2, 'numeric'::answer_type, '11.25', '10²⁷ W', false, NULL, false, NULL, 'd = 50 × 9.46 × 10¹⁵ = 4.730 × 10¹⁷ m. L = 4π × (4.730 × 10¹⁷)² × 4.0 × 10⁻⁹ = 1.12 × 10²⁸ W. Mark scheme (3 marks). C1: ly to m. C1: L = 4πd²F. A1: L = 11.2 × 10²⁷ W.', 3, NULL, NULL),
('9457f2ee-f5e5-5849-8480-a59290f17ceb', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 35, 35, 'Which step is needed to use a standard candle?', NULL, 2, 'multiple_choice'::answer_type, 'Measure the radiant flux intensity received at the Earth', NULL, false, NULL, false, NULL, 'Known L and measured F give d. Mark scheme (3 marks). C1: measure F. C1: L known. A1: D (Measure the radiant flux intensity received at the Earth).', 3, NULL, NULL),
('2263cdf0-d027-5085-8479-85ea9a40ff63', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 36, 36, 'Sunlight at the top of the Earth''s atmosphere has an intensity of 1.36 kW m⁻², 1.50 × 10¹¹ m from the Sun. Calculate the Sun''s luminosity, in units of 10²⁶ W.', NULL, 2, 'numeric'::answer_type, '3.845', '10²⁶ W', false, NULL, false, NULL, 'L = 4πd²F = 4π × (1.50 × 10¹¹)² × 1.36 × 10³ = 3.85 × 10²⁶ W. Mark scheme (4 marks). M1: L = 4πd²F. C1: kW to W. C1: value. A1: L = 3.85 × 10²⁶ W.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg35032bfb-t fg35032bfb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg35032bfb-t">Sunlight at the Earth</title><desc id="fg35032bfb-d">The Sun and the Earth 1.50 × 10¹¹ m apart; the intensity at the top of the Earth''s atmosphere is 1.36 kW m⁻².</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="59" y1="62" x2="64" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="55.2" y1="71.2" x2="58.7" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="75" x2="46" y2="80" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.8" y1="71.2" x2="33.3" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="62" x2="28" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.8" y1="52.8" x2="33.3" y2="49.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="49" x2="46" y2="44" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="55.2" y1="52.8" x2="58.7" y2="49.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46" cy="62" r="10" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Sun</text><circle cx="414" cy="62" r="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="414" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><text x="414" y="90" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.36 kW m⁻²</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="409.1" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="414,116 407.7,119 407.7,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="230" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.50 × 10¹¹ m</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="414" y1="74" x2="414" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'The Sun and the Earth 1.50 × 10¹¹ m apart; the intensity at the top of the Earth''s atmosphere is 1.36 kW m⁻².'),
('9e91fa48-af9c-589a-991a-0e5ba25f9e0b', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 37, 37, 'Calculate the flux intensity from the Sun (L = 3.8 × 10²⁶ W) at Jupiter, 7.8 × 10¹¹ m away.', NULL, 2, 'numeric'::answer_type, '49.7', 'W m⁻²', false, NULL, false, NULL, 'F = 3.8 × 10²⁶ ÷ (4π × (7.8 × 10¹¹)²) = 49.7 W m⁻². Mark scheme (3 marks). C1: formula. C1: value. A1: F = 49.7 W m⁻².', 3, NULL, NULL),
('41dd1253-82b2-5c20-8e58-0409bacbb51e', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 38, 38, 'Astronomers check distances found with Cepheids against another method for nearby stars. Which method is used for the nearest stars?', NULL, 2, 'multiple_choice'::answer_type, 'Stellar parallax', NULL, false, NULL, false, NULL, 'Parallax calibrates the distance ladder. Mark scheme (3 marks). C1: parallax. C1: calibration. A1: B (Stellar parallax).', 3, NULL, NULL),
('819144fe-cc90-542a-921d-537d39ba9305', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 39, 39, 'Two identical Cepheids have the same period. One appears 25 times brighter than the other. Calculate (distance of fainter) ÷ (distance of brighter).', NULL, 2, 'numeric'::answer_type, '5', NULL, false, NULL, false, NULL, 'Same L, so d ∝ 1/√F: ratio = √25 = 5.0. Mark scheme (3 marks). C1: same luminosity. C1: √ of flux ratio. A1: ratio = 5.0.', 3, NULL, NULL),
('c34c7305-6d14-5022-8237-8c0353175736', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 40, 40, 'A star of luminosity 7.6 × 10²⁸ W is 2.5 × 10¹⁸ m away. Calculate the flux intensity in units of 10⁻¹⁰ W m⁻².', NULL, 2, 'numeric'::answer_type, '9.677', '10⁻¹⁰ W m⁻²', false, NULL, false, NULL, 'F = 7.6 × 10²⁸ ÷ (4π × (2.5 × 10¹⁸)²) = 9.68 × 10⁻¹⁰ W m⁻². Mark scheme (3 marks). C1: formula. C1: value. A1: F = 9.68 × 10⁻¹⁰ W m⁻².', 3, NULL, NULL),
('eb9d2e71-2fcd-574f-af90-e1824052852e', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 41, 41, 'Why is a single, very distant type 1a supernova more useful than a Cepheid for measuring the distance to its galaxy?', NULL, 2, 'multiple_choice'::answer_type, 'It is far more luminous, so it can be seen at much greater distances', NULL, false, NULL, false, NULL, 'Peak luminosities around 10³⁶ W are detectable across the Universe. Mark scheme (4 marks). C1: very high luminosity. C1: visible at great distance. C1: still a standard candle. A1: C (It is far more luminous, so it can be seen at much greater distances).', 4, NULL, NULL),
('418163b5-0efe-5557-b522-27b0828764f1', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 42, 42, 'A detector on a telescope of area 0.50 m² collects 2.0 × 10⁻¹² W from a star. Calculate the radiant flux intensity, in units of 10⁻¹² W m⁻².', NULL, 2, 'numeric'::answer_type, '4', '10⁻¹² W m⁻²', false, NULL, false, NULL, 'F = P/A = 2.0 × 10⁻¹² ÷ 0.50 = 4.0 × 10⁻¹² W m⁻². Mark scheme (3 marks). C1: F = P/A. C1: value. A1: F = 4.0 × 10⁻¹² W m⁻².', 3, NULL, NULL),
('cc5a2aaf-7beb-5287-9187-772d241555b7', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 43, 43, 'A Cepheid of luminosity 6.0 × 10²⁹ W is observed in a nearby galaxy, giving a flux intensity of 2.5 × 10⁻¹³ W m⁻². (a) Calculate the distance in m. (b) Express it in light-years (1 ly = 9.46 × 10¹⁵ m). Give only the answer to (b), in units of 10⁶ ly.', NULL, 3, 'numeric'::answer_type, '0.0462', '10⁶ ly', false, NULL, false, NULL, '(a) d = √(6.0 × 10²⁹ ÷ (4π × 2.5 × 10⁻¹³)) = 4.370 × 10²⁰ m. (b) 4.370 × 10²⁰ ÷ 9.46 × 10¹⁵ = 4.62 × 10⁴ ly. Mark scheme (5 marks). C1: d formula. C1: value in m. M1: m to ly. C1: value. A1: d = 0.0462 × 10⁶ ly.', 5, NULL, NULL),
('b57f43c6-6594-52a8-adea-85fbf85bc604', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 44, 44, 'A star X is 4.0 × 10¹⁷ m away and gives a flux of 5.0 × 10⁻⁹ W m⁻². Star Y gives a flux of 2.0 × 10⁻¹⁰ W m⁻² and has 4.0 times the luminosity of X. (a) Calculate the luminosity of X. (b) Calculate the luminosity of Y. (c) Calculate the distance of Y. Give only the answer to (c), in units of 10¹⁸ m.', NULL, 3, 'numeric'::answer_type, '4', '10¹⁸ m', false, NULL, false, NULL, '(a) L = 4π × (4.0 × 10¹⁷)² × 5.0 × 10⁻⁹ = 1.005 × 10²⁸ W. (b) 4.0 × 1.005 × 10²⁸ = 4.021 × 10²⁸ W. (c) d = √(4.021 × 10²⁸ ÷ (4π × 2.0 × 10⁻¹⁰)) = 4.00 × 10¹⁸ m. Mark scheme (6 marks). C1: L of X. C1: L of Y. M1: d = √(L/4πF). C1: substitution. C1: value. A1: d = 4.00 × 10¹⁸ m.', 6, NULL, NULL),
('5d5dfb59-2e88-554e-b2ad-000858191202', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 45, 45, 'A solar panel of area 2.0 m² on a probe near Mars (2.3 × 10¹¹ m from the Sun, L = 3.8 × 10²⁶ W) is 20% efficient. (a) Calculate the flux intensity at Mars. (b) Calculate the electrical power produced.', NULL, 3, 'numeric'::answer_type, '228.7', 'W', false, NULL, false, NULL, '(a) F = 3.8 × 10²⁶ ÷ (4π × (2.3 × 10¹¹)²) = 571.6 W m⁻². (b) P = 0.20 × 2.0 × 571.6 = 229 W. Mark scheme (5 marks). C1: flux. M1: P = efficiency × FA. C1: substitution. C1: value. A1: P = 229 W.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg75de2526-t fg75de2526-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg75de2526-t">Probe near Mars</title><desc id="fg75de2526-d">The Sun, of luminosity 3.8 × 10²⁶ W, and a probe near Mars 2.3 × 10¹¹ m away carrying a solar panel of area 2.0 m².</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="59" y1="62" x2="64" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="55.2" y1="71.2" x2="58.7" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="75" x2="46" y2="80" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.8" y1="71.2" x2="33.3" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="62" x2="28" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.8" y1="52.8" x2="33.3" y2="49.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="49" x2="46" y2="44" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="55.2" y1="52.8" x2="58.7" y2="49.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46" cy="62" r="10" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Sun</text><text x="46" y="90" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.8 × 10²⁶ W</text><circle cx="414" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="414" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">probe</text><text x="414" y="90" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">panel 2.0 m²</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="409.1" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="414,116 407.7,119 407.7,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="230" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.3 × 10¹¹ m</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="414" y1="74" x2="414" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'The Sun, of luminosity 3.8 × 10²⁶ W, and a probe near Mars 2.3 × 10¹¹ m away carrying a solar panel of area 2.0 m².'),
('208eef8f-cda8-511d-955e-067a6697e0ca', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 46, 46, 'Dust between the Earth and a standard candle absorbs 20% of its light. The candle''s luminosity is 3.0 × 10²⁹ W and the flux received is 1.2 × 10⁻¹² W m⁻². (a) Calculate the distance assuming no absorption. (b) Calculate the true distance. (c) Calculate the percentage error in (a). Give only the answer to (b), in units of 10²⁰ m.', NULL, 3, 'numeric'::answer_type, '1.262', '10²⁰ m', false, NULL, false, NULL, '(a) √(3.0 × 10²⁹ ÷ (4π × 1.2 × 10⁻¹²)) = 1.410 × 10²⁰ m. (b) True flux without dust = 1.2 × 10⁻¹² ÷ 0.80 = 1.5 × 10⁻¹²; d = √(3.0 × 10²⁹ ÷ (4π × 1.5 × 10⁻¹²)) = 1.26 × 10²⁰ m. (c) About 12% too large. Mark scheme (6 marks). C1: naive distance. M1: correct the flux. C1: true distance. C1: value. C1: percentage error. A1: d = 1.26 × 10²⁰ m.', 6, NULL, NULL),
('82d7e772-83e1-51d6-b41f-e16dcd179e7e', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 47, 47, 'Two Cepheids have periods that imply luminosities in the ratio 3.0 : 1. The brighter-luminosity one gives 1.5 times the flux of the other. (a) Write L = 4πd²F for each. (b) Calculate (distance of the more luminous) ÷ (distance of the less luminous).', NULL, 3, 'numeric'::answer_type, '1.414', NULL, false, NULL, false, NULL, '(a) L₁ = 4πd₁²F₁, L₂ = 4πd₂²F₂. (b) d₁/d₂ = √((L₁/L₂) ÷ (F₁/F₂)) = √(3.0 ÷ 1.5) = 1.41. Mark scheme (5 marks). B1: both equations. M1: divide. C1: substitution. C1: value. A1: ratio = 1.41.', 5, NULL, NULL),
('e5c5ce08-de36-5e74-a773-b7c1d3897aec', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 48, 48, 'The Sun (L = 3.8 × 10²⁶ W) is seen from a star 4.0 × 10¹⁶ m away. (a) Calculate the flux intensity received there from the Sun. (b) A telescope there has a mirror of area 1.0 m². Calculate the power it collects from the Sun. (c) Taking photons of 550 nm (energy 3.6 × 10⁻¹⁹ J), calculate the photons collected per second. Give only the answer to (b), in units of 10⁻⁸ W.', NULL, 3, 'numeric'::answer_type, '1.89', '10⁻⁸ W', false, NULL, false, NULL, '(a) F = 3.8 × 10²⁶ ÷ (4π × (4.0 × 10¹⁶)²) = 1.890 × 10⁻⁸ W m⁻². (b) P = 1.890 × 10⁻⁸ × 1.0 = 1.89 × 10⁻⁸ W. (c) ≈ 5.2 × 10¹⁰ photons per second. Mark scheme (6 marks). C1: flux. M1: P = FA. C1: value. C1: photon rate. B1: units. A1: P = 1.89 × 10⁻⁸ W.', 6, NULL, NULL),
('032c88d5-a730-54df-a90e-f22b85e81e51', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 49, 49, 'A galaxy contains a type 1a supernova of peak luminosity 8.0 × 10³⁵ W. Its peak flux at the Earth is 5.0 × 10⁻¹⁶ W m⁻². (a) Calculate its distance. (b) Express it in Mpc (1 Mpc = 3.09 × 10²² m).', NULL, 3, 'numeric'::answer_type, '365.2', 'Mpc', false, NULL, false, NULL, '(a) d = √(8.0 × 10³⁵ ÷ (4π × 5.0 × 10⁻¹⁶)) = 1.128 × 10²⁵ m. (b) 1.128 × 10²⁵ ÷ 3.09 × 10²² = 365 Mpc. Mark scheme (5 marks). C1: formula. C1: value. M1: m to Mpc. C1: value. A1: d = 365 Mpc.', 5, NULL, NULL),
('f0c0c775-7bbe-5acd-a80f-d9a5163e48d7', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', 'c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'a-level', '31.1', '9702 coursebook 31.1 · Standard candles and luminosity', 50, 50, 'Earth receives 1.36 kW m⁻² from the Sun at 1.50 × 10¹¹ m. (a) Calculate the solar flux at Venus, 1.08 × 10¹¹ m from the Sun. (b) Calculate the flux at Saturn, 1.43 × 10¹² m from the Sun. Give only the answer to (a), in kW m⁻².', NULL, 3, 'numeric'::answer_type, '2.623', 'kW m⁻²', false, NULL, false, NULL, '(a) F = 1.36 × (1.50 × 10¹¹ ÷ 1.08 × 10¹¹)² = 2.62 kW m⁻². (b) 1.36 × (1.50 ÷ 14.3)² ≈ 0.015 kW m⁻². Mark scheme (6 marks). M1: inverse square ratio. C1: substitution. C1: value. C1: Saturn. B1: units. A1: F = 2.62 kW m⁻².', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 250" role="img" aria-labelledby="fg5f0a062b-t fg5f0a062b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5f0a062b-t">Venus, Earth and Saturn</title><desc id="fg5f0a062b-d">The Sun with Venus at 1.08 × 10¹¹ m, the Earth at 1.50 × 10¹¹ m and Saturn at 1.43 × 10¹² m; the Earth receives 1.36 kW m⁻². Not to scale.</desc><line x1="46" y1="62" x2="454" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="59" y1="62" x2="64" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="55.2" y1="71.2" x2="58.7" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="75" x2="46" y2="80" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.8" y1="71.2" x2="33.3" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="62" x2="28" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.8" y1="52.8" x2="33.3" y2="49.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="49" x2="46" y2="44" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="55.2" y1="52.8" x2="58.7" y2="49.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46" cy="62" r="10" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Sun</text><circle cx="215.5" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="215.5" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Venus</text><circle cx="281.4" cy="62" r="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="281.4" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><text x="281.4" y="90" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.36 kW m⁻²</text><circle cx="454" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="454" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Saturn</text><polygon