('7732c9b5-27f5-50ac-81cf-33996ee6b650', 'eb9d2e71-2fcd-574f-af90-e1824052852e', 'It is far more luminous, so it can be seen at much greater distances', 'C', true, 2),
('48c10a65-0280-5e80-a377-3ba7148cbf9e', 'eb9d2e71-2fcd-574f-af90-e1824052852e', 'It does not need a flux measurement', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('58c0ad42-a895-5dc8-b50e-02eebace8522', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 7, 7, 'Sirius has a luminosity of 9.7 × 10²⁷ W and is 8.1 × 10¹⁶ m away. Calculate the radiant flux intensity at the Earth, in units of 10⁻⁸ W m⁻².', NULL, 1, 'numeric'::answer_type, '11.76', '10⁻⁸ W m⁻²', false, NULL, false, NULL, 'F = 9.7 × 10²⁷ ÷ (4π × (8.1 × 10¹⁶)²) = 1.18 × 10⁻⁷ W m⁻². Mark scheme (2 marks). C1: F = L/4πd². A1: F = 11.8 × 10⁻⁸ W m⁻².', 2, NULL, NULL),
('1eea68f5-e3b1-583b-90da-a630c4b132fd', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 8, 8, 'What is the radiant flux intensity received from a star?', NULL, 1, 'multiple_choice'::answer_type, 'The power from the star passing through unit area at right angles to the light', NULL, false, NULL, false, NULL, 'It is the power per unit area at the observer: F = L/4πd². Mark scheme (1 mark). B1: C (The power from the star passing through unit area at right angles to the light).', 1, NULL, NULL),
('4bd16b03-c22a-5c7d-87e6-48148bec11b7', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 9, 9, 'A star of luminosity 4.0 × 10²⁶ W is at a distance where the flux intensity is 2.0 × 10⁻⁸ W m⁻². Calculate the area of the sphere over which its power is spread, in units of 10³⁴ m².', NULL, 1, 'numeric'::answer_type, '2', '10³⁴ m²', false, NULL, false, NULL, 'A = L/F = 4.0 × 10²⁶ ÷ 2.0 × 10⁻⁸ = 2.0 × 10³⁴ m². Mark scheme (2 marks). C1: A = L/F. A1: A = 2.0 × 10³⁴ m².', 2, NULL, NULL),
('bd82c5c3-186d-54f1-a0ba-493963c17702', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 10, 10, 'The luminosity of a star doubles while its distance stays the same. What happens to the flux received?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'F = L/4πd², so at fixed d the flux is proportional to L. Mark scheme (1 mark). B1: A (It doubles).', 1, NULL, NULL),
('12b81b26-a0b5-5560-93b7-2349960221a0', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 11, 11, 'A star gives a flux intensity of 60 W m⁻² at one distance. Calculate the flux at four times that distance.', NULL, 1, 'numeric'::answer_type, '3.75', 'W m⁻²', false, NULL, false, NULL, 'F = 60 ÷ 4² = 3.75 W m⁻². Mark scheme (2 marks). C1: inverse square. A1: F = 3.75 W m⁻².', 2, NULL, NULL),
('a3172950-f294-5148-bb5a-db14c506d034', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 12, 12, 'How does the flux intensity F depend on the distance d from a star?', NULL, 1, 'multiple_choice'::answer_type, 'F ∝ 1/d²', NULL, false, NULL, false, NULL, 'Power spreads over 4πd². Mark scheme (1 mark). B1: D (F ∝ 1/d²).', 1, NULL, NULL),
('86715a00-5ac2-5d09-b827-c61afa507c2f', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 13, 13, 'A star''s flux intensity at the Earth is 3.0 × 10⁻⁹ W m⁻² and it is 6.0 × 10¹⁷ m away. Calculate its luminosity, in units of 10²⁷ W.', NULL, 1, 'numeric'::answer_type, '13.57', '10²⁷ W', false, NULL, false, NULL, 'L = 4πd²F = 4π × (6.0 × 10¹⁷)² × 3.0 × 10⁻⁹ = 1.36 × 10²⁸ W. Mark scheme (2 marks). C1: L = 4πd²F. A1: L = 13.6 × 10²⁷ W.', 2, NULL, NULL),
('b15bbce9-f733-5109-ad68-f8a4e8560dcc', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 14, 14, 'Why is a nearby dim star sometimes brighter in the sky than a distant luminous one?', NULL, 1, 'multiple_choice'::answer_type, 'Flux depends on distance as well as luminosity', NULL, false, NULL, false, NULL, 'F = L/4πd²: a small d can outweigh a small L. Mark scheme (1 mark). B1: B (Flux depends on distance as well as luminosity).', 1, NULL, NULL),
('766395ec-4b8a-595c-b0cd-5538c253203a', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 15, 15, 'The Sun (luminosity 3.8 × 10²⁶ W) is 5.8 × 10¹⁰ m from Mercury. Calculate the solar flux at Mercury, in kW m⁻².', NULL, 1, 'numeric'::answer_type, '8.989', 'kW m⁻²', false, NULL, false, NULL, 'F = 3.8 × 10²⁶ ÷ (4π × (5.8 × 10¹⁰)²) = 8989 W m⁻². In kW m⁻²: 8989 ÷ 10³ = 8.99. Mark scheme (2 marks). C1: formula. A1: F = 8.99 kW m⁻².', 2, NULL, NULL),
('51f5846b-ff5b-5587-bbe8-9b3489e0b263', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 16, 16, 'Which quantity is the same for all observers of a star, wherever they are?', NULL, 1, 'multiple_choice'::answer_type, 'Its luminosity', NULL, false, NULL, false, NULL, 'L is a property of the star itself. Mark scheme (1 mark). B1: C (Its luminosity).', 1, NULL, NULL),
('e9af49ef-44b1-5d07-bd4d-25c7545e5750', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 17, 17, 'A star''s flux at the Earth is 2.5 × 10⁻¹⁰ W m⁻². How much power falls on a telescope mirror of area 4.0 m²?', NULL, 1, 'numeric'::answer_type, '1e-9', 'W', false, NULL, false, NULL, 'P = FA = 2.5 × 10⁻¹⁰ × 4.0 = 1.0 × 10⁻⁹ W. Mark scheme (2 marks). C1: P = FA. A1: P = 1.0 × 10⁻⁹ W.', 2, NULL, NULL),
('31445092-4d0f-5d3a-8ea7-dcbc2580c4bf', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 18, 18, 'In the formula F = L/4πd², what does 4πd² represent?', NULL, 1, 'multiple_choice'::answer_type, 'The surface area of a sphere of radius d centred on the star', NULL, false, NULL, false, NULL, 'The power spreads uniformly over this sphere. Mark scheme (1 mark). B1: A (The surface area of a sphere of radius d centred on the star).', 1, NULL, NULL),
('05f0068e-d25b-559e-86b7-22a3db802b81', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 19, 19, 'Two stars have the same luminosity. Star P is 5.0 times further away than star Q. Calculate (flux from Q) ÷ (flux from P).', NULL, 1, 'numeric'::answer_type, '25', NULL, false, NULL, false, NULL, 'F ∝ 1/d²: ratio = 5.0² = 25. Mark scheme (2 marks). C1: inverse square. A1: ratio = 25.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg077f4bd6-t fg077f4bd6-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg077f4bd6-t">Two stars of equal luminosity</title><desc id="fg077f4bd6-d">Stars Q and P have the same luminosity; Q is at distance d from the Earth and P at 5.0d. Not to scale.</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><circle cx="46" cy="62" r="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><line x1="198.5" y1="62" x2="203.5" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="195.3" y1="69.8" x2="198.9" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="187.5" y1="73" x2="187.5" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="179.8" y1="69.8" x2="176.2" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="176.5" y1="62" x2="171.5" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="179.8" y1="54.2" x2="176.2" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="187.5" y1="51" x2="187.5" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="195.3" y1="54.2" x2="198.9" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="187.5" cy="62" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="187.5" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Q</text><line x1="425" y1="62" x2="430" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="421.8" y1="69.8" x2="425.3" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="414" y1="73" x2="414" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="406.2" y1="69.8" x2="402.7" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="403" y1="62" x2="398" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="406.2" y1="54.2" x2="402.7" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="414" y1="51" x2="414" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="421.8" y1="54.2" x2="425.3" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="414" cy="62" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="414" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">P</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="182.6" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="187.5,116 181.2,119 181.2,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="116.8" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">d</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="187.5" y1="74" x2="187.5" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><polygon points="46,146 52.3,143 52.3,149" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="146" x2="409.1" y2="146" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="414,146 407.7,149 407.7,143" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="230" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0d</text><line x1="46" y1="74" x2="46" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="414" y1="74" x2="414" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><text x="452" y="182" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">not to scale</text></svg>', 'Stars Q and P have the same luminosity; Q is at distance d from the Earth and P at 5.0d. Not to scale.'),
('68628752-150d-5772-88ef-27d3977e515d', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 20, 20, 'A star is twice as far away as another of the same luminosity. What fraction of the nearer star''s flux do we receive from it?', NULL, 1, 'multiple_choice'::answer_type, 'One quarter', NULL, false, NULL, false, NULL, 'F ∝ 1/d², so doubling d gives 1/2² = 1/4. Mark scheme (1 mark). B1: D (One quarter).', 1, NULL, NULL),
('6fdaf058-109f-5ef5-893d-48d6a358d205', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 21, 21, 'A lamp of power 60 W radiates equally in all directions. Calculate the intensity 2.0 m away.', NULL, 1, 'numeric'::answer_type, '1.194', 'W m⁻²', false, NULL, false, NULL, 'I = 60 ÷ (4π × 2.0²) = 1.19 W m⁻². Mark scheme (2 marks). C1: I = P/4πd². A1: I = 1.19 W m⁻².', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 240" role="img" aria-labelledby="fg88ef23d8-t fg88ef23d8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg88ef23d8-t">Lamp radiating in all directions</title><desc id="fg88ef23d8-d">A 60 W lamp radiating equally in all directions, with a detector 2.0 m away on a sphere centred on the lamp.</desc><path d="M269.2,235 A230,230 0 0,0 269.2,5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="82.8" y1="125.7" x2="121" y2="142.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,144.4 118.8,144.5 120.9,139.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="122.9" x2="124.6" y2="131.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,132.5 122.8,133.8 123.9,128.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="84" y1="120" x2="125.8" y2="120" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,120 124.6,122.5 124.6,117.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="117.1" x2="124.6" y2="108.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,107.5 123.9,111.1 122.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="82.8" y1="114.3" x2="121" y2="97.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,95.6 120.9,100.1 118.8,95.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><circle cx="70" cy="120" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="146" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">60 W</text><rect x="296" y="110" width="10" height="20" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polygon points="70,166 76.3,163 76.3,169" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="166" x2="295.1" y2="166" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,166 293.7,169 293.7,163" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185" y="178" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 m</text></svg>', 'A 60 W lamp radiating equally in all directions, with a detector 2.0 m away on a sphere centred on the lamp.'),
('0a08808a-1595-5797-94b3-e5b9ba61097d', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 22, 22, 'A star of luminosity 1.0 × 10²⁸ W is 1.0 × 10¹⁸ m away. Calculate the flux intensity in units of 10⁻¹⁰ W m⁻².', NULL, 1, 'numeric'::answer_type, '7.958', '10⁻¹⁰ W m⁻²', false, NULL, false, NULL, 'F = 1.0 × 10²⁸ ÷ (4π × (1.0 × 10¹⁸)²) = 7.96 × 10⁻¹⁰ W m⁻². Mark scheme (1 mark). A1: F = 7.96 × 10⁻¹⁰ W m⁻².', 1, NULL, NULL),
('35df4303-5b8e-523b-bf71-3da746c5e148', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 23, 23, 'Polaris has a luminosity of 8.6 × 10²⁹ W and gives a flux of 1.6 × 10⁻⁹ W m⁻² at the Earth. Calculate its distance in units of 10¹⁸ m.', NULL, 1, 'numeric'::answer_type, '6.54', '10¹⁸ m', false, NULL, false, NULL, 'd = √(8.6 × 10²⁹ ÷ (4π × 1.6 × 10⁻⁹)) = 6.54 × 10¹⁸ m. Mark scheme (2 marks). C1: d = √(L/4πF). A1: d = 6.54 × 10¹⁸ m.', 2, NULL, NULL),
('f1c0fb31-1b30-51b4-8b7c-13ab479bdbc3', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 24, 24, 'Star A has 100 times the luminosity of star B but appears equally bright. Calculate (distance of A) ÷ (distance of B).', NULL, 2, 'numeric'::answer_type, '10', NULL, false, NULL, false, NULL, 'Equal F: d ∝ √L, so ratio = √100 = 10. Mark scheme (3 marks). C1: F equal. C1: √ of L ratio. A1: ratio = 10.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg84b816c8-t fg84b816c8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg84b816c8-t">Equally bright stars</title><desc id="fg84b816c8-d">Star B of luminosity L and star A of luminosity 100L appear equally bright from the Earth. Not to scale.</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><circle cx="46" cy="62" r="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><line x1="210.3" y1="62" x2="215.3" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207.1" y1="69.8" x2="210.6" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199.3" y1="73" x2="199.3" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="191.6" y1="69.8" x2="188" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-