('a84a6f7b-7ca9-5769-bd28-793464c9680a', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 25, 25, 'A star 2.0 × 10¹⁷ m away gives a flux of 8.0 × 10⁻⁹ W m⁻². Calculate the flux received from it at a planet 5.0 × 10¹⁶ m from the star.', NULL, 2, 'numeric'::answer_type, '1.28e-7', 'W m⁻²', false, NULL, false, NULL, 'F₂ = F₁(d₁/d₂)² = 8.0 × 10⁻⁹ × (2.0 × 10¹⁷ ÷ 5.0 × 10¹⁶)² = 1.28 × 10⁻⁷ W m⁻². Mark scheme (3 marks). C1: inverse square ratio. C1: value. A1: F = 1.28 × 10⁻⁷ W m⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg41a39b3f-t fg41a39b3f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg41a39b3f-t">Star, planet and Earth</title><desc id="fg41a39b3f-d">A star with a planet 5.0 × 10¹⁶ m from it and the Earth 2.0 × 10¹⁷ m from it; the flux at the Earth is 8.0 × 10⁻⁹ W m⁻².</desc><line x1="46" y1="62" x2="404.7" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="57" y1="62" x2="62" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="53.8" y1="69.8" x2="57.3" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="73" x2="46" y2="78" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="38.2" y1="69.8" x2="34.7" y2="73.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="35" y1="62" x2="30" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="38.2" y1="54.2" x2="34.7" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="51" x2="46" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="53.8" y1="54.2" x2="57.3" y2="50.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46" cy="62" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">star</text><circle cx="135.7" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="135.7" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">planet</text><circle cx="404.7" cy="62" r="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="404.7" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><text x="404.7" y="90" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8.0 × 10⁻⁹ W m⁻²</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="130.8" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="135.7,116 129.3,119 129.3,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="90.8" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0 × 10¹⁶ m</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="135.7" y1="74" x2="135.7" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><polygon points="46,146 52.3,143 52.3,149" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="146" x2="399.8" y2="146" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="404.7,146 398.3,149 398.3,143" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="225.3" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 × 10¹⁷ m</text><line x1="46" y1="74" x2="46" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="404.7" y1="74" x2="404.7" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'A star with a planet 5.0 × 10¹⁶ m from it and the Earth 2.0 × 10¹⁷ m from it; the flux at the Earth is 8.0 × 10⁻⁹ W m⁻².'),
('7097549d-cb60-56d3-a8dd-31907ddec6da', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 26, 26, 'Why can radiant flux intensity be measured directly but luminosity cannot?', NULL, 2, 'multiple_choice'::answer_type, 'Flux is what a detector on Earth receives; luminosity also needs the distance', NULL, false, NULL, false, NULL, 'L = 4πd²F, so finding L also needs the distance d. Mark scheme (3 marks). C1: F measured. C1: d needed for L. A1: B (Flux is what a detector on Earth receives; luminosity also needs the distance).', 3, NULL, NULL),
('c07be86e-87c3-547d-8f29-72594c5a2b56', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 27, 27, 'A star of luminosity 2.0 × 10²⁸ W gives a flux of 1.1 × 10⁻¹⁰ W m⁻². Calculate its distance in light-years (1 ly = 9.46 × 10¹⁵ m).', NULL, 2, 'numeric'::answer_type, '402.1', 'ly', false, NULL, false, NULL, 'd = √(2.0 × 10²⁸ ÷ (4π × 1.1 × 10⁻¹⁰)) = 3.804 × 10¹⁸ m. In ly: 3.804 × 10¹⁸ ÷ 9.46 × 10¹⁵ = 402. Mark scheme (4 marks). C1: rearrange. C1: value in m. C1: m to ly. A1: d = 402 ly.', 4, NULL, NULL),
('20331d5a-0eaa-5f08-8ecf-c4378044e893', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '26443cb9-a498-4768-a082-b6366197eb43', 'a-level', '31.2', '9702 coursebook 31.2 · Luminosity and radiant flux intensity', 28, 28, 'The flux from the Sun at the Earth is 1.36 kW m⁻². Calculate the flux at Neptune, which is 30 times further from the Sun.', NULL, 2, 'numeric'::answer_type, '1.511', 'W m⁻²', false, NULL, false, NULL, 'F = 1360 ÷ 30² = 1.51 W m⁻². Mark scheme (3 marks). C1: inverse square. C1: value. A1: F = 1.51 W m⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg6b4a243c-t fg6b4a243c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6b4a243c-t">Earth and Neptune</title><desc id="fg6b4a243c-d">The Sun with the Earth at distance d, where the flux is 1.36 kW m⁻², and Neptune at 30d. Not to scale.</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="59" y1="62" x2="64" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="55.2" y1="71.2" x2="58.7" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46" y1="75" x2="46" y2="80" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.8" y1="71.2" x2="33.3" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="62" x2="28" y2="62" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.8" y1="52.8" x2="33.3" y2="49.3" style="stroke:var(--fig-accent-2,#b45309);stroke-wid