('786c67d4-9c28-5faa-a52a-4263226b9df9', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 9, 9, 'A spectral line of laboratory wavelength 656 nm is observed at 663 nm in the light from a galaxy. Calculate the galaxy''s speed of recession, in units of 10⁶ m s⁻¹. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '3.201', '10⁶ m s⁻¹', false, NULL, false, NULL, 'v = cΔλ/λ = 3.00 × 10⁸ × (663 − 656) ÷ 656 = 3.20 × 10⁶ m s⁻¹. Mark scheme (2 marks). C1: Δλ/λ = v/c. A1: v = 3.20 × 10⁶ m s⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 214" role="img" aria-labelledby="fg48cee7c2-t fg48cee7c2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg48cee7c2-t">Redshifted line</title><desc id="fg48cee7c2-d">A spectral line at 656 nm in the laboratory spectrum appears at 663 nm in the spectrum of a galaxy.</desc><rect x="104" y="34" width="332" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="94" y="50" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">laboratory</text><rect x="104" y="106" width="332" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="94" y="122" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">galaxy</text><line x1="253.4" y1="34" x2="253.4" y2="66" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="253.4" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">656 nm</text><line x1="282.4" y1="106" x2="282.4" y2="138" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="282.4" y="151" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">663 nm</text><line x1="253.4" y1="66" x2="282.4" y2="106" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="104" y1="168" x2="436" y2="168" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="168" x2="104" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="104" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">620</text><line x1="187" y1="168" x2="187" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="187" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">640</text><line x1="270" y1="168" x2="270" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="270" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">660</text><line x1="353" y1="168" x2="353" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="353" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">680</text><line x1="436" y1="168" x2="436" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="436" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">700</text><text x="270" y="206" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">wavelength / nm</text></svg>', 'A spectral line at 656 nm in the laboratory spectrum appears at 663 nm in the spectrum of a galaxy.'),
('06a2c715-6cab-50e6-8026-0944a537748b', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 10, 10, 'What is meant by redshift?', NULL, 1, 'multiple_choice'::answer_type, 'An increase in the observed wavelength of light from a receding source', NULL, false, NULL, false, NULL, 'Δλ/λ ≈ v/c for a receding source. Mark scheme (1 mark). B1: C (An increase in the observed wavelength of light from a receding source).', 1, NULL, NULL),
('658f0399-da55-552e-88f7-56e3ced09844', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 11, 11, 'A galaxy is 3.0 × 10²⁴ m away. Taking H₀ = 2.3 × 10⁻¹⁸ s⁻¹, calculate its recession speed, in units of 10⁶ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '6.9', '10⁶ m s⁻¹', false, NULL, false, NULL, 'v = H₀d = 2.3 × 10⁻¹⁸ × 3.0 × 10²⁴ = 6.9 × 10⁶ m s⁻¹. Mark scheme (2 marks). C1: v = H₀d. A1: v = 6.9 × 10⁶ m s⁻¹.', 2, NULL, NULL),
('96d79967-a7f6-5e32-b6d8-5da90518a786', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 12, 12, 'What does Hubble''s law say about galaxies?', NULL, 1, 'multiple_choice'::answer_type, 'Their speed of recession is proportional to their distance', NULL, false, NULL, false, NULL, 'Hubble''s law is v = H₀d, so recession speed ∝ distance. Mark scheme (1 mark). B1: A (Their speed of recession is proportional to their distance).', 1, NULL, NULL),
('9a4e7557-ee24-533d-a707-80b9298dcc98', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 13, 13, 'A galaxy recedes at 1.5 × 10⁷ m s⁻¹. Taking H₀ = 2.3 × 10⁻¹⁸ s⁻¹, calculate its distance, in units of 10²⁴ m.', NULL, 1, 'numeric'::answer_type, '6.522', '10²⁴ m', false, NULL, false, NULL, 'd = v/H₀ = 1.5 × 10⁷ ÷ 2.3 × 10⁻¹⁸ = 6.52 × 10²⁴ m. Mark scheme (2 marks). C1: d = v/H₀. A1: d = 6.52 × 10²⁴ m.', 2, NULL, NULL),
('7afaf3f2-5fef-5edd-9340-07d90607a161', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 14, 14, 'Which observation suggests that the Universe is expanding?', NULL, 1, 'multiple_choice'::answer_type, 'Light from distant galaxies is redshifted, more for more distant galaxies', NULL, false, NULL, false, NULL, 'Recession speed grows with distance. Mark scheme (1 mark). B1: D (Light from distant galaxies is redshifted, more for more distant galaxies).', 1, NULL, NULL),
('b6e6f680-61ed-5476-bf90-003f1d2d0e5f', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 15, 15, 'A galaxy recedes at 6.0 × 10⁶ m s⁻¹. Calculate the fractional change in wavelength Δλ/λ of its light. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '0.02', NULL, false, NULL, false, NULL, 'Δλ/λ = v/c = 6.0 × 10⁶ ÷ 3.00 × 10⁸ = 0.020. Mark scheme (2 marks). C1: Δλ/λ = v/c. A1: Δλ/λ = 0.020.', 2, NULL, NULL),
('7a1eeb87-7f36-5ea5-b3be-d5335276d05a', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 16, 16, 'What is the cosmic microwave background radiation?', NULL, 1, 'multiple_choice'::answer_type, 'Radiation left over from the hot early Universe, now cooled to about 2.7 K', NULL, false, NULL, false, NULL, 'It is strong evidence for the Big Bang. Mark scheme (1 mark). B1: B (Radiation left over from the hot early Universe, now cooled to about 2.7 K).', 1, NULL, NULL),
('76b61f0b-3942-5066-a7ad-3ca136f969e3', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 17, 17, 'Taking H₀ = 2.3 × 10⁻¹⁸ s⁻¹, estimate the age of the Universe in years (1 year = 3.16 × 10⁷ s), in units of 10¹⁰ years.', NULL, 1, 'numeric'::answer_type, '1.376', '10¹⁰ years', false, NULL, false, NULL, 'T ≈ 1/H₀ = 1 ÷ 2.3 × 10⁻¹⁸ = 4.348 × 10¹⁷ s, which is 4.348 × 10¹⁷ ÷ 3.16 × 10⁷ = 1.38 × 10¹⁰ years. Mark scheme (2 marks). C1: T = 1/H₀ then years. A1: T = 1.38 × 10¹⁰ years.', 2, NULL, NULL),
('bec7bf5b-06cd-516f-bad9-3cd9c35d17d7', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 18, 18, 'Light from a galaxy is blueshifted. What does this show?', NULL, 1, 'multiple_choice'::answer_type, 'The galaxy is moving towards us', NULL, false, NULL, false, NULL, 'Approach shortens the observed wavelength. Mark scheme (1 mark). B1: C (The galaxy is moving towards us).', 1, NULL, NULL),
('370eb15f-dc51-54fc-a84d-50dde8a23162', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 19, 19, 'A line with laboratory wavelength 500 nm is seen at 510 nm. Calculate Δλ/λ.', NULL, 1, 'numeric'::answer_type, '0.02', NULL, false, NULL, false, NULL, 'Δλ/λ = (510 − 500) ÷ 500 = 0.020. Mark scheme (2 marks). C1: Δλ ÷ λ. A1: Δλ/λ = 0.020.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 214" role="img" aria-labelledby="fg8ca80800-t fg8ca80800-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8ca80800-t">Shifted line</title><desc id="fg8ca80800-d">A line at 500 nm in the laboratory spectrum is seen at 510 nm in the observed spectrum.</desc><rect x="104" y="34" width="332" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="94" y="50" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">laboratory</text><rect x="104" y="106" width="332" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="94" y="122" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">observed</text><line x1="270" y1="34" x2="270" y2="66" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="270" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">500 nm</text><line x1="311.5" y1="106" x2="311.5" y2="138" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="311.5" y="151" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">510 nm</text><line x1="270" y1="66" x2="311.5" y2="106" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="104" y1="168" x2="436" y2="168" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="168" x2="104" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="104" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">460</text><line x1="187" y1="168" x2="187" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="187" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">480</text><line x1="270" y1="168" x2="270" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="270" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">500</text><line x1="353" y1="168" x2="353" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="353" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">520</text><line x1="436" y1="168" x2="436" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="436" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">540</text><text x="270" y="206" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">wavelength / nm</text></svg>', 'A line at 500 nm in the laboratory spectrum is seen at 510 nm in the observed spectrum.'),
('ad8071d0-16b0-555d-87f8-f099ae64889c', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 20, 20, 'In Hubble''s law, what are the units of H₀ in SI?', NULL, 1, 'multiple_choice'::answer_type, 's⁻¹', NULL, false, NULL, false, NULL, 'H₀ = v/d: (m s⁻¹) ÷ m. Mark scheme (1 mark). B1: A (s⁻¹).', 1, NULL, NULL),
('95ecfe5b-b7b8-5326-8aff-54da403483b3', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 21, 21, 'A galaxy recedes at 2.1 × 10⁶ m s⁻¹. A line emitted at 486 nm is observed at a longer wavelength. Calculate the shift Δλ, in nm. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '3.402 nm', 'nm', false, NULL, false, NULL, 'Δλ = λv/c = 486 × 2.1 × 10⁶ ÷ 3.00 × 10⁸ = 3.40 nm. Mark scheme (2 marks). C1: Δλ = λv/c. A1: Δλ = 3.40 nm.', 2, NULL, NULL),
('2fe838b1-9dab-5108-beea-1e696f53a999', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 22, 22, 'What is the Big Bang theory?', NULL, 1, 'multiple_choice'::answer_type, 'The Universe began from an extremely hot, dense state and has been expanding ever since', NULL, false, NULL, false, NULL, 'Supported by redshift and the cosmic microwave background. Mark scheme (1 mark). B1: D (The Universe began from an extremely hot, dense state and has been expanding ever since).', 1, NULL, NULL),
('00b02283-3b34-5231-822b-b137c3efe751', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 23, 23, 'Express a distance of 100 Mpc in metres, in units of 10²⁴ m (1 Mpc = 3.09 × 10²² m).', NULL, 1, 'numeric'::answer_type, '3.09', '10²⁴ m', false, NULL, false, NULL, 'd = 100 × 3.09 × 10²² = 3.09 × 10²⁴ m. Mark scheme (2 marks). C1: × 3.09 × 10²². A1: d = 3.09 × 10²⁴ m.', 2, NULL, NULL),
('1e7272b7-84e4-5bf5-8b30-d33315d23cae', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 24, 24, 'Why must galaxies used to test Hubble''s law have distances measured independently, for example with standard candles?', NULL, 1, 'multiple_choice'::answer_type, 'Hubble''s law relates speed to distance, so both must be measured separately to test it', NULL, false, NULL, false, NULL, 'Redshift gives v; standard candles give d. Mark scheme (1 mark). B1: B (Hubble''s law relates speed to distance, so both must be measured separately to test it).', 1, NULL, NULL),
('b8023046-dcfd-552f-9543-40430b5b5a9e', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 25, 25, 'Taking H₀ = 2.3 × 10⁻¹⁸ s⁻¹, how fast is a galaxy at a distance of 5.0 × 10²⁴ m moving away from us? Give the speed in units of 10⁷ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.15', '10⁷ m s⁻¹', false, NULL, false, NULL, 'v = 2.3 × 10⁻¹⁸ × 5.0 × 10²⁴ = 1.15 × 10⁷ m s⁻¹. Mark scheme (1 mark). A1: v = 1.15 × 10⁷ m s⁻¹.', 1, NULL, NULL),
('70275a06-d451-515f-b795-7ec476bb17b2', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 26, 26, 'A line of laboratory wavelength 393 nm is observed at 405 nm from a galaxy. Taking H₀ = 2.3 × 10⁻¹⁸ s⁻¹, calculate the distance of the galaxy, in units of 10²⁵ m. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '0.3983', '10²⁵ m', false, NULL, false, NULL, 'v = 3.00 × 10⁸ × (405 − 393) ÷ 393 = 9.160 × 10⁶ m s⁻¹. d = 9.160 × 10⁶ ÷ 2.3 × 10⁻¹⁸ = 3.98 × 10²⁴ m. Mark scheme (3 marks). C1: v from redshift. C1: d = v/H₀. A1: d = 0.398 × 10²⁵ m.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 214" role="img" aria-labelledby="fgbbaea449-t fgbbaea449-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbbaea449-t">Redshifted line</title><desc id="fgbbaea449-d">A line at 393 nm in the laboratory spectrum appears at 405 nm in the spectrum of a galaxy.</desc><rect x="104" y="34" width="332" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="94" y="50" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">laboratory</text><rect x="104" y="106" width="332" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="94" y="122" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">galaxy</text><line x1="240.9" y1="34" x2="240.9" y2="66" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="240.9" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">393 nm</text><line x1="290.8" y1="106" x2="290.8" y2="138" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="290.8" y="151" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">405 nm</text><line x1="240.9" y1="66" x2="290.8" y2="106" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="104" y1="168" x2="436" y2="168" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="168" x2="104" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="104" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">360</text><line x1="187" y1="168" x2="187" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="187" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">380</text><line x1="270" y1="168" x2="270" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="270" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">400</text><line x1="353" y1="168" x2="353" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="353" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">420</text><line x1="436" y1="168" x2="436" y2="173" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="436" y="184" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">440</text><text x="270" y="206" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">wavelength / nm</text></svg>', 'A line at 393 nm in the laboratory spectrum appears at 405 nm in the spectrum of a galaxy.'),
('6707dfe2-2f52-531a-b3f7-233f3263d8a9', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 27, 27, 'H₀ is often quoted as 70 km s⁻¹ Mpc⁻¹. Convert it to s⁻¹ (1 Mpc = 3.09 × 10²² m), in units of 10⁻¹⁸ s⁻¹.', NULL, 2, 'numeric'::answer_type, '2.265', '10⁻¹⁸ s⁻¹', false, NULL, false, NULL, 'H₀ = 70 × 10³ ÷ 3.09 × 10²² = 2.27 × 10⁻¹⁸ s⁻¹. Mark scheme (4 marks). M1: km to m. C1: Mpc to m. C1: value. A1: H₀ = 2.27 × 10⁻¹⁸ s⁻¹.', 4, NULL, NULL),
('5213babc-031d-5872-9d70-7bab06a4ec77', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 28, 28, 'Why does 1/H₀ give an estimate of the age of the Universe?', NULL, 2, 'multiple_choice'::answer_type, 'If expansion has been at constant speed, every galaxy took time d/v = 1/H₀ to reach its present distance', NULL, false, NULL, false, NULL, 'd/v is the same for all galaxies. Mark scheme (3 marks). C1: d/v. C1: constant expansion assumed. A1: C (If expansion has been at constant speed, every galaxy took time d/v = 1/H₀ to reach its present distance).', 3, NULL, NULL),
('14d17e8c-867e-5d24-9361-d0bea09e8d55', '8695e833-9d29-4367-bfd6-0c20aebb2b1d', '397b2565-7a2c-5e16-a138-021d30b81dd9', 'a-level', '31.4', '9702 coursebook 31.4 · Hubble’s law and the Big Bang', 29, 29, 'A galaxy 200 Mpc away recedes at 1.4 × 10⁴ km s⁻¹. Calculate H₀ in km s⁻¹ Mpc⁻¹.', NULL, 2, 'numeric'::answer_type, '70', 'km s⁻¹ Mpc⁻¹', false, NULL, false, NULL, 'H₀ = v/d = 1.4 × 10⁴ ÷ 200 = 70 km s⁻¹ Mpc⁻¹. Mark scheme (3 marks). C1: H₀ = v/d. C1: value. A1: H₀ = 70 km s⁻¹ Mpc⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgc29368cd-t fgc29368cd-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc29368cd-t">Galaxy on a Hubble graph</title><desc id="fgc29368cd-d">A galaxy plotted at distance 200 Mpc and recession speed 1.4 × 10⁴ km s⁻¹, on a line through the origin.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="34" x2="100" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170.5" y1="34" x2="170.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="241" y1="34" x2="241" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="311.5" y1="34" x2="311.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:ro